"""Loss-of-Function curation steps."""

from __future__ import annotations

from pydantic import BaseModel

from pps.session import Session


class IngestionSettings(BaseModel):
    """Settings for `ingestion`."""

    lof_curation_dataset_path: str
    """Path of the curated LOF dataset."""
    lof_curation_variant_annotations_path: str
    """Path of the resulting variant annotations."""


def ingestion(session: Session, settings: IngestionSettings) -> None:
    """Step to ingest the Loss-of-Function dataset generated by OTAR2075.

    Ported from `legacy_gentropy.lof_curation_ingestion.LOFIngestionStep`.
    """
    raise NotImplementedError
